def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as f:
        for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
    return h.hexdigest()

def event(name,**kw):
    row={'event':name,'utc':datetime.now(timezone.utc).isoformat()};row.update(kw)
    with print_lock:print(json.dumps(row),flush=True)

def accepted(relative,config_hash=None):
    p=root/relative;r=json.loads(p.read_text())
    if not r.get('passed'):raise RuntimeError('execution not accepted: '+relative)
    if config_hash and r.get('job_configuration_sha256')!=config_hash:raise RuntimeError('accepted configuration mismatch')
    hashes={relative:digest(p)}
    for rel,h in r['result_sha256'].items():
        if digest(root/rel)!=h:raise RuntimeError('accepted artifact changed: '+rel)
        hashes[rel]=h
    return r,hashes

def checkpoint_state(indices=None,job_id=None):
    paths=[]
    if indices is None:
        for d in (raw,group,phase,piece):paths.extend(d.rglob('*.wl'))
    else:
        for i in indices:
            paths.append(raw/('component_'+str(i).zfill(4)+'.wl'))
            for d in (group,phase):paths.extend(d.glob('component_'+str(i)+'_*.wl'))
        if job_id:
            for d in piece.glob('kernel_'+job_id+'_batch_*'):paths.extend(d.glob('*.wl'))
    rows=[]
    for p in sorted(set(paths)):
        try:
            st=p.stat()
            if p.is_file():rows.append((str(p.relative_to(root)),st.st_size,st.st_mtime_ns))
        except FileNotFoundError:pass
    return {'files':len(rows),'bytes':sum(r[1] for r in rows),'identity':hashlib.sha256(repr(rows).encode()).hexdigest()}

def watch(j,jid,cfg_hash):
    rp=root/j['execution_result'];lp=root/j['log'];last=None;lastchange=time.monotonic();missing=0
    while not rp.exists():
        p=subprocess.run(['qstat','-j',jid],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=30)
        size=lp.stat().st_size if lp.exists() else 0
        state=(p.returncode,size)
        if state!=last:
            last=state;lastchange=time.monotonic()
            tail=''
            if size:
                with lp.open('rb') as f:f.seek(max(0,size-2200));tail=f.read().decode(errors='replace')
            hp=root/j['heartbeat'];beat=json.loads(hp.read_text()) if hp.exists() else {}
            event('NATIVE_PROGRESS',job_id=jid,log_bytes=size,tail=tail,heartbeat=beat)
        missing=missing+1 if p.returncode else 0
        if missing>=6:raise RuntimeError('job disappeared without receipt: '+jid)
        if size and time.monotonic()-lastchange>j['limits']['inactivity_seconds']+180:raise RuntimeError('native job stalled: '+jid)
        time.sleep(30)
    r=json.loads(rp.read_text())
    if r.get('job_id')!=jid or r.get('job_configuration_sha256')!=cfg_hash:raise RuntimeError('native receipt identity mismatch: '+jid)
    failures=[l for l in lp.read_text(errors='replace').splitlines() if 'FAIL:' in l] if lp.exists() else []
    event('STAGE_FINISHED',job_id=jid,passed=r.get('passed'),reason=r.get('reason'),failures=failures[-12:])
    if failures:raise RuntimeError('native check failed: '+jid)
    return r

def archive_receipt(relative,tag):
    p=root/relative
    if not p.exists():return
    r=json.loads(p.read_text())
    if r.get('passed'):raise RuntimeError('refusing to archive accepted output: '+relative)
    a=root/('.cluster/s08_result/'+tag+'_prior_'+str(r['job_id'])+'_execution.json')
    if a.exists():raise RuntimeError('archive already exists: '+str(a))
    p.replace(a)

def submit(j,tag):
    cfg='.cluster/'+tag+'_job.json';cp=root/cfg;sp=root/('.cluster/s08_result/'+tag+'_submission.json')
    if cp.exists() or sp.exists():raise RuntimeError('job generation already exists: '+tag)
    j['log']='cache/'+tag+'.log';j['heartbeat']='cache/'+tag+'_heartbeat.json'
    for k in ('MATHEMATICA_USERBASE','WOLFRAM_USERBASE'):j['environment'][k]='{root}/cache/wolfram_'+tag
    cp.write_text(json.dumps(j,indent=2,sort_keys=True)+'\n')
    args=['qsub','-terse','-N','pSIDIS_'+tag,'-S','/bin/bash','-pe','shared','4','-l','h_rt='+time.strftime('%H:%M:%S',time.gmtime(j['limits']['wall_seconds']+300))+',h_data=10G','-wd',str(root),'-j','y','-o',str(root/('cache/'+tag+'_scheduler.log'))]
    script='#!/bin/bash\nset -eu\nexport LC_ALL=C LANG=C\nexec python3 '+str(root/'.cluster/s02_execute.py')+' --root '+str(root)+' --job '+cfg+'\n'
    p=subprocess.run(args,input=script,stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True)
    if p.returncode:raise RuntimeError(p.stderr)
    jid=p.stdout.strip().split('.')[0]
    if not jid.isdigit():raise RuntimeError('invalid scheduler job id')
    row={'job_id':jid,'config':cfg,'configuration_sha256':digest(cp),'qsub':args,'script':script}
    sp.write_text(json.dumps(row,indent=2)+'\n');event('SUBMITTED',**row)
    return jid,digest(cp)

def batch_config(base,dependencies,index):
    owner='Hgg/s08_partition_'+str(index).zfill(2)
    j=json.loads(json.dumps(base));j['command'][-1]='{root}/'+entry
    j['reviewed_sha256'].update(dependencies);j['reviewed_sha256'][entry]=entry_hash
    j['environment'].update(POLARIZED_SIDIS_PARTITION_COUNT='4',POLARIZED_SIDIS_PARTITION_INDEX=str(index),POLARIZED_SIDIS_PARTITION_CHECK='0')
    j['execution_result']=owner+'_result/s08_execution.json'
    j['expected_results']=[owner+'_result/s08_result.wl',owner+'_result/s08_checks.json',owner+'_control_result/s08_result.wl']
    j['success_marker']='PASS: s08_Hgg_partition_components';j['limits']['scratch_bytes']=24*1024**3;j['limits']['wall_seconds']=10500
    return j

current_jobs={1:('14914444','258b2a4b80f4ddb14d6cb9990f1b4ac6c68fa5812d7d8f4c536c26e0852d1f87'),2:('14912716','0d7210e62da287dde7fac82707fac12248b47a5e437b5f1f14e0a542eb3b1576'),3:('14912715','14ebb7597151b5860dce99d86eea91aceec332a7154808cc9c9cfdbec680230a'),4:('14913210','26250ea480c8e5542f76a0958f243210859d1ac425cbab01d03f2a6be1538049')}
def prepare():
    if digest(root/base_relative)!=base_hash or digest(root/entry)!=entry_hash:raise RuntimeError('reviewed continuation source changed')
    base=json.loads((root/base_relative).read_text());current={};dependencies={}
    for index,(jid,h) in current_jobs.items():
        prefix='s08_Hgg_parallel_groups_batch_' if index==1 else ('s08_Hgg_metric_recovery_batch_' if index==4 else 's08_Hgg_early_cancel_batch_')
        rel='.cluster/'+prefix+str(index).zfill(2)+'_20260925_part1_job.json';cp=root/rel
        if digest(cp)!=h:raise RuntimeError('current batch configuration changed')
        j=json.loads(cp.read_text());current[index]=(j,jid,h)
        if j['command'][-1] not in ('{root}/common/s08_map_Hgg_early_affine_partitioned.wls','{root}/common/s08_map_Hgg_metric_partitioned.wls','{root}/common/s08_map_Hgg_parallel_groups.wls'):raise RuntimeError('different current production entry')
        for name,value in j['reviewed_sha256'].items():
            if digest(root/name)!=value or name in dependencies and dependencies[name]!=value:raise RuntimeError('current scientific input changed: '+name)
            dependencies[name]=value
    relative='Hgg/s08_affine_cancel_exact_result/s08_execution.json'
    proof,proof_hashes=accepted(relative,'324fe7df01f7e62098633caf48e1318d74e52bb7e901442281b365723ba2fdda')
    if digest(root/relative)!='8f67f0535f76d7606f7d0dc4b8062e9dad9dab2b964dae245a1179bcfd609bd2':raise RuntimeError('early-Cancel receipt changed')
    for block in (base['reviewed_sha256'],proof_hashes,proof['reviewed_sha256']):
        for name,value in block.items():
            if digest(root/name)!=value or name in dependencies and dependencies[name]!=value:raise RuntimeError('accepted dependency conflict: '+name)
            dependencies[name]=value
    reader,reader_hashes=accepted('Hgg/s08_metric_reader_result/s08_execution.json','6e71ab41a8a74e52174041e4ced96a5d1de0571b7c56e0e1d29b41bc4fb78401')
    for block in (reader_hashes,reader['reviewed_sha256']):
        for name,value in block.items():
            if digest(root/name)!=value or name in dependencies and dependencies[name]!=value:raise RuntimeError('reader dependency conflict: '+name)
            dependencies[name]=value
    parts=json.loads((root/'Hgg/s08_partition_interface_result/s08_checks.json').read_text())['partitions']
    if len(parts)!=len(current):raise RuntimeError('accepted native partitions changed')
    event('EARLY_CANCEL_INPUTS_ACCEPTED',entry=entry,entry_sha256=entry_hash,proof=relative)
    return base,dependencies,parts,current

def restart_slowest(j,jid):
    import signal,xml.etree.ElementTree as ET
    rp=root/j['execution_result']
    if rp.exists():return False
    lp=root/j['log'];failures=[line for line in lp.read_text().splitlines() if 'FAIL:' in line]
    if failures:raise RuntimeError('existing slowest batch has a native failure')
    beat=json.loads((root/j['heartbeat']).read_text())
    if beat.get('job_id')!=jid:raise RuntimeError('slowest heartbeat identity mismatch')
    p=subprocess.run(['qstat','-u','rushil','-xml'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=30)
    if p.returncode:raise RuntimeError(p.stderr)
    jobs=[node for node in ET.fromstring(p.stdout).iter('job_list') if node.findtext('JB_job_number')==jid]
    if len(jobs)!=1:raise RuntimeError('slowest batch has no unique running allocation')
    queue=jobs[0].findtext('queue_name') or ''
    if '@' not in queue:raise RuntimeError('slowest batch is not running')
    host=queue.split('@')[-1];pid=int(beat['pid'])
    code="import os,signal,json,time;from pathlib import Path;p=Path('/proc')/str("+str(pid)+");cmd=(p/'cmdline').read_bytes().replace(bytes([0]),b' ').decode();env=(p/'environ').read_bytes().split(bytes([0]));assert p.stat().st_uid==os.getuid();assert 'WolframKernel' in cmd and 's08_map_Hgg_metric_partitioned.wls' in cmd;assert b'JOB_ID="+jid+"' in env;assert os.getpgid("+str(pid)+")=="+str(pid)+";os.killpg("+str(pid)+",signal.SIGTERM);time.sleep(15)\nif p.exists(): os.killpg("+str(pid)+",signal.SIGKILL)\nprint('CHECKPOINT_RESTART_REQUESTED')"
    import shlex
    command='env LC_ALL=C LANG=C python3 -c '+shlex.quote(code)
    p=subprocess.run(['ssh','-o','BatchMode=yes','-o','ConnectTimeout=15',host,command],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=45)
    if p.returncode:raise RuntimeError('owned checkpoint restart failed: '+p.stderr)
    event('CHECKPOINT_RESTART_FOR_GROUP_DISPATCH',job_id=jid,node=host,pid=pid,output=p.stdout.strip())
    return True

def run_batch(base,dependencies,index,indices,current):
    previous,jid,h=current
    requested=False
    event('ADOPT_EXISTING_BATCH',index=index,job_id=jid,configuration_sha256=h)
    if requested:restart_slowest(previous,jid)
    r=watch(previous,jid,h)
    if r.get('passed'):
        accepted(previous['execution_result']);event('BATCH_ACCEPTED',index=index,job_id=jid);return previous['execution_result']
    if r.get('reason')!='wall_limit' and not (requested and r.get('reason')=='normal_exit' and r.get('exit_code')!=0):raise RuntimeError('existing batch requires inspection: '+jid)
    if not checkpoint_state(indices,jid)['files']:raise RuntimeError('no preserved checkpoints')
    j=batch_config(base,dependencies,index)
    for attempt in range(1,17):
        tag='s08_Hgg_parallel_groups_long_batch_'+str(index).zfill(2)+'_20260925_part'+str(attempt)
        rp=root/j['execution_result']
        if rp.exists():
            r=json.loads(rp.read_text())
            if r.get('passed'):accepted(j['execution_result']);return j['execution_result']
            archive_receipt(j['execution_result'],tag)
        before=checkpoint_state(indices)
        jid,h=submit(j,tag);r=watch(j,jid,h);after=checkpoint_state(indices,jid)
        event('BATCH_CHECKPOINTS',index=index,job_id=jid,before=before,after=after)
        if r.get('passed'):
            accepted(j['execution_result']);event('BATCH_ACCEPTED',index=index,job_id=jid);return j['execution_result']
        if r.get('reason')!='wall_limit' or before==after:raise RuntimeError('batch requires inspection: '+jid)
        event('RESUME_FROM_NEW_CHECKPOINTS',index=index,job_id=jid)
    raise RuntimeError('checkpoint generation bound reached')

def run():
    base,dependencies,parts,current=prepare();completed=[];errors=[]
    with ThreadPoolExecutor(max_workers=len(parts)) as pool:
        pending={pool.submit(run_batch,base,dependencies,i+1,indices,current[i+1]):i+1 for i,indices in enumerate(parts)}
        for future in as_completed(pending):
            try:completed.append(future.result())
            except Exception as exc:errors.append(str(exc));event('BATCH_ERROR',index=pending[future],error=str(exc))
    if errors:raise RuntimeError('; '.join(errors))
    for relative in completed:
        _,hashes=accepted(relative);dependencies.update(hashes)
    j=json.loads(json.dumps(base));j['reviewed_sha256'].update(dependencies);j['limits']['scratch_bytes']=24*1024**3
    jid,h=submit(j,'s08_Hgg_partition_closure_20260925')
    watch(j,jid,h);accepted(j['execution_result']);event('MAPPING_ACCEPTED',job_id=jid,receipt=j['execution_result'])
try:run()
except Exception as exc:event('CONTROLLER_ERROR',error=str(exc));traceback.print_exc()
finally:event('CONTROLLER_EXIT')
